+  margin: 0;
+  background: var(--report-paper);
+  color: var(--report-ink);
+  font-family: var(--report-font-body);
+  font-size: 1rem;
+}
+
+.report-shell {
+  display: grid;
+  grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem);
+  gap: var(--report-space-5);
+  max-width: var(--report-page-max);
+  margin: 0 auto;
+  padding: var(--report-space-6) var(--report-space-5);
+}
+
+.report-main {
+  min-width: 0;
+}
+
+.report-cover,
+.chapter-hero,
+.tactic-card,
+.example-card,
+.good-bad,
+.stats-strip,
+.facts-table-wrap,
+.details-note,
+.industry-card,
+.priority-group,
+.checklist-card,
+.source-card,
+.myth-callout {
+  break-inside: avoid;
+  page-break-inside: avoid;
+}
+
+.report-cover {
+  margin-block-end: var(--report-space-7);
+  padding: clamp(2rem, 7vw, 4rem);
+  background: var(--report-paper-raised);
+  border: 1px solid var(--report-rule);
+  border-radius: var(--report-radius-xl);
+}
+
+.report-kicker,
+.eyebrow,
+.meta-label,
+.badge,
+.priority-label {
+  font-size: 0.75rem;
+  font-weight: 700;
+  letter-spacing: 0.08em;
+  line-height: 1.35;
+  text-transform: uppercase;
+}
+
+.report-kicker,
+.eyebrow {
+  color: var(--report-blue);
+  margin: 0 0 var(--report-space-2);
+}
+
+.report-title,
+.chapter-title {
+  margin: 0;
+  color: var(--report-ink);
+  font-family: var(--report-font-heading);
+  font-weight: 600;
+  letter-spacing: -0.03em;
+}
+
+.report-title {
+  max-width: 12ch;
+  font-size: clamp(3rem, 8vw, 4rem);
+  line-height: 1.05;
+}
+
+.report-subtitle,
+.chapter-summary {
+  max-width: 62ch;
+  color: var(--report-ink-muted);
+  font-size: clamp(1.05rem, 2vw, 1.25rem);
+}
+
+.report-meta-grid {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: var(--report-space-3);
+  margin-block-start: var(--report-space-5);
+  padding-block-start: var(--report-space-4);
+  border-block-start: 1px solid var(--report-rule);
+}
+
+.meta-item {
+  min-width: 0;
+}
+
+.meta-label {
+  display: block;
+  color: var(--report-ink-soft);
+}
+
+.meta-value {
+  display: block;
+  color: var(--report-ink);
+  font-weight: 650;
+}
+
+.sticky-toc {
+  position: sticky;
+  top: var(--report-space-4);
+  align-self: start;
+  max-height: calc(100vh - var(--report-space-5));
+  overflow: auto;
+  padding: var(--report-space-3);
+  background: rgba(255, 253, 248, 0.94);
+  border: 1px solid var(--report-rule);
+  border-radius: var(--report-radius-lg);
+  box-shadow: 0 12px 32px rgba(17, 24, 39, 0.1);
+}
+
+.sticky-toc h2 {
+  margin: 0 0 var(--report-space-2);
+  color: var(--report-ink);
+  font-size: 0.875rem;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+}
+
+.sticky-toc ol {
+  display: grid;
+  gap: var(--report-space-1);
+  margin: 0;
+  padding: 0;
+  list-style: none;
+}
+
+.sticky-toc a {
+  display: block;
+  padding: var(--report-space-1) var(--report-space-2);
+  border-left: 3px solid transparent;
+  color: var(--report-ink-muted);
+  text-decoration: none;
+}
+
+.sticky-toc a[aria-current="true"],
+.sticky-toc a:hover,
+.sticky-toc a:focus-visible {
+  border-left-color: var(--report-blue);
+  color: var(--report-ink);
+  outline: none;
+}
+
+.chapter-hero {
+  margin-block: var(--report-space-6) var(--report-space-4);
+  padding: var(--report-space-5);
+  background: var(--report-paper-raised);
+  border: 1px solid var(--report-rule);
+  border-radius: var(--report-radius-xl);
+}
+
+.chapter-title {
+  font-size: clamp(2rem, 5vw, 2.75rem);
+  line-height: 1.12;
+}
+
+.action-line {
+  display: flex;
+  flex-wrap: wrap;
+  gap: var(--report-space-2) var(--report-space-3);
+  align-items: baseline;
+  margin-block: var(--report-space-4);
+  padding: var(--report-space-3) var(--report-space-4);
+  background: var(--report-ink);
+  color: #ffffff;
+  border-radius: var(--report-radius-md);
+}
+
+.action-line strong {
+  font-weight: 750;
+}
+
+.badge-row {
+  display: flex;
+  flex-wrap: wrap;
+  gap: var(--report-space-2);
+  align-items: center;
+}
+
+.badge {
+  display: inline-flex;
+  gap: var(--report-space-1);
+  align-items: center;
+  width: fit-content;
+  padding: 0.25rem 0.625rem;
+  border-radius: 9999px;
+  border: 1px solid transparent;
+  white-space: nowrap;
+}
+
+.badge--rct {
+  background: var(--report-good-bg);
+  color: var(--report-green);
+  border-color: rgba(20, 122, 74, 0.2);
+}
+
+.badge--strong {
+  background: #eaf2ff;
+  color: #1d4ed8;
+  border-color: rgba(37, 99, 235, 0.2);
+}
+
+.badge--vendor {
+  background: #f4ecff;
+  color: var(--report-violet);
+  border-color: rgba(109, 40, 217, 0.2);
+}
+
+.badge--practitioner {
+  background: #fff5db;
+  color: #92400e;
+  border-color: rgba(183, 121, 31, 0.24);
+}
+
+.badge--hygiene {
+  background: #f3f4f6;
+  color: #374151;
+  border-color: rgba(55, 65, 81, 0.18);
+}

