body:
![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

While restricting the parsing to lines before the first blank line is a great improvement, the parser can still produce false positives if the input is not an HTTP response at all (e.g., a plain error message or a JSON body) but happens to contain lines matching the header pattern.

To make this robust, we should ensure that the first non-empty line of the response starts with `HTTP/`. If it does not, we should exit immediately and avoid parsing any headers or status codes.

```suggestion
	printf '%s\n' "$response_text" | awk -v name="$header_name" '
		BEGIN { target = tolower(name) ":" }
		{ line = $0; sub(/\r$/, "", line); if (line == "") { if (started) exit; next } }
		!started { if (line !~ /^HTTP\//) exit; started = 1 }
		{ lower = tolower(line); if (index(lower, target) == 1) { sub(/^[^:]*:[[:space:]]*/, "", line); print line; exit } }
	' 2>/dev/null
	return 0
}

_gh_secondary_cooldown_status() {
	local response_text="$1"
	printf '%s\n' "$response_text" | awk '
		{ line = $0; sub(/\r$/, "", line); if (line == "") { if (started) exit; next } }
		!started { if (line !~ /^HTTP\//) exit; started = 1 }
		line ~ /^HTTP\// { split(line, parts, /[[:space:]]+/); print parts[2]; exit }
	' 2>/dev/null || printf ''
	return 0
}
```

